-- Safety predicate vectors: normalization, IPv4, single label, and
-- null/empty inputs mirror the sender verdicts (strict subset).
SELECT pg_temp.assert_true(private.manual_document_domain_is_safe('shop.example.com'), 'safe domain verifies');
SELECT pg_temp.assert_true(private.manual_document_domain_is_safe('  Shop.Example.COM./ '), 'cased host with trailing dot verifies');
SELECT pg_temp.assert_true(NOT private.manual_document_domain_is_safe('1.2.3.4'), 'ipv4 fails safe');
SELECT pg_temp.assert_true(NOT private.manual_document_domain_is_safe('no-tld'), 'single label fails safe');
SELECT pg_temp.assert_true(NOT private.manual_document_domain_is_safe(NULL), 'null fails safe');
SELECT pg_temp.assert_true(NOT private.manual_document_domain_is_safe(''), 'empty fails safe');
SELECT pg_temp.assert_true(NOT private.manual_document_domain_is_safe('1.2.3.4a'), 'strict corner fails safe');
UPDATE public.order_notification_outbox SET status = 'processing', locked_by = 'm2-worker', locked_at = now(), dispatch_started_at = NULL WHERE order_id = '10000000-0000-4000-8000-000000000017' AND event_type = 'manual_order_invoice';
